using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;

public partial class ActorAudioOperations
{
    private sealed class Guard : IDisposable {private readonly Godot.Mutex _mutex;public Guard(Settings state){_mutex=state["cache_mutex"].As<Godot.Mutex>();_mutex.Lock();}public void Dispose()=>_mutex.Unlock();}
    private static Settings Dict(Settings source,string key)=>source.TryGetValue(key,out var value)?value.AsGodotDictionary():new Settings();
    private static string Text(Settings source,string key,string fallback="")=>source.TryGetValue(key,out var value)?value.AsString():fallback;
    private static long Int(Settings source,string key,long fallback=0)=>source.TryGetValue(key,out var value)?value.AsInt64():fallback;
    private static double Number(Settings source,string key,double fallback=0)=>source.TryGetValue(key,out var value)?value.AsDouble():fallback;
    private static bool Cancelled(RefCounted? job)=>job!=null&&job.Call("is_cancelled").AsBool();
    private static string SourcePath(Variant value)=>value.VariantType==Variant.Type.Nil?"":value.ToString();
    public void invalidate(Settings state,string path){using var guard=new Guard(state);state["generation"]=Int(state,"generation")+1;if(path.Length==0){Dict(state,"sources").Clear();Dict(state,"metadata").Clear();Dict(state,"identities").Clear();state["retained_bytes"]=0L;}else{string key=path_key(path);forget_locked(state,key);Dict(state,"metadata").Remove(key);}}
    public Settings source_stamp(Settings state,Variant value){if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is AudioStream stream)return new Settings {["key"]="stream:"+stream.GetInstanceId(),["missing"]=false};string path=SourcePath(value);if(path.Length==0)return new Settings {["key"]="",["missing"]=true};var metadata=file_metadata(state,path_key(path),false);return new Settings {["key"]=Text(metadata,"stamp"),["missing"]=Int(metadata,"size",-1)<0};}
    public Settings file_metadata(Settings state,string path,bool force)
    {
        long now=(long)Time.GetTicksMsec(),generation;using(new Guard(state)){var prior=Dict(Dict(state,"metadata"),path);if(!force&&prior.Count>0&&now<Int(prior,"checked_until"))return prior.Duplicate();generation=Int(state,"generation");}var current=signature(path);using(new Guard(state)){if(generation!=Int(state,"generation"))return new Settings();var all=Dict(state,"metadata");var prior=Dict(all,path);if(!force&&prior.Count>0&&now<Int(prior,"checked_until"))return prior.Duplicate();if(prior.Count==0||Int(prior,"size")!=Int(current,"size")||Int(prior,"modified")!=Int(current,"modified")){forget_locked(state,path);long revision=Int(state,"revision")+1;state["revision"]=revision;prior=new Settings {["size"]=current["size"],["modified"]=current["modified"],["stamp"]=path+":"+Int(current,"modified")+":"+Int(current,"size")+":"+revision,["duration"]=-1.0};}prior["checked_until"]=now+1000;all[path]=prior;prune_metadata_locked(state,path);return prior.Duplicate();}
    }
    public AudioStream? source(Settings state,Variant value,RefCounted? job)
    {
        if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is AudioStream stream)return stream;string path=SourcePath(value);if(path.Length==0)return null;path=path_key(path);var metadata=file_metadata(state,path,false);if(Int(metadata,"size",-1)<0)return null;Settings load;using(new Guard(state)){var cached=cached_locked(state,path,Text(metadata,"stamp"));if(cached!=null)return cached;var loads=Dict(state,"loads");load=Dict(loads,path);if(load.Count==0){load=new Settings {["mutex"]=new Godot.Mutex(),["users"]=0L};loads[path]=load;}load["users"]=Int(load,"users")+1;}var gate=load["mutex"].As<Godot.Mutex>();while(!gate.TryLock()){if(Cancelled(job)){release_load(state,path,load);return null;}OS.DelayMsec(10);}try{return load_source(state,path,job);}finally{gate.Unlock();release_load(state,path,load);}
    }
    public void release_load(Settings state,string path,Settings load){using var guard=new Guard(state);long users=Int(load,"users")-1;load["users"]=users;if(users==0)Dict(state,"loads").Remove(path);}
    public Settings pcm_info(Settings state,string path){path=path_key(path);var metadata=file_metadata(state,path,false);if(Int(metadata,"size",-1)<0)return new Settings {["error"]="Missing source."};if(metadata.TryGetValue("pcm_info",out var prior))return prior.AsGodotDictionary().Duplicate();using var pcm=new AudioPcmFileOperations();var info=pcm.inspect(path);using(new Guard(state)){var current=Dict(Dict(state,"metadata"),path);if(Text(current,"stamp")==Text(metadata,"stamp")){current["pcm_info"]=info.Duplicate();if(Text(info,"error","invalid").Length==0)current["duration"]=info["duration"];}}return info;}
    public double file_duration(Settings state,Variant value,RefCounted? job){if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is AudioStream existing)return existing.GetLength();string path=SourcePath(value);if(path.Length==0)return 0;var metadata=file_metadata(state,path_key(path),false);if(Number(metadata,"duration",-1)>=0)return Number(metadata,"duration");string extension=path.GetExtension().ToLowerInvariant();if(extension=="wav"){var info=pcm_info(state,path);if(Text(info,"error","invalid").Length==0)return Number(info,"duration");}else if(extension=="flac"){flac_pcm_bytes(state,path);var updated=file_metadata(state,path_key(path),false);if(Number(updated,"duration",-1)>=0)return Number(updated,"duration");}return source(state,value,job)?.GetLength()??0;}
    public bool needs_file_preview(Settings state,Variant value){if(value.VariantType!=Variant.Type.String)return false;string path=value.AsString();if(path.GetExtension().ToLowerInvariant()=="wav")return Int(file_metadata(state,path_key(path),false),"size")>64L*1024*1024;if(path.GetExtension().ToLowerInvariant()=="flac"){long bytes=flac_pcm_bytes(state,path);return bytes<0||bytes>128L*1024*1024-4096;}return false;}
    public AudioStream? load_source(Settings state,string path,RefCounted? job)
    {
        if(Cancelled(job))return null;var metadata=file_metadata(state,path,false);if(Int(metadata,"size",-1)<0)return null;long generation;using(new Guard(state)){var cached=cached_locked(state,path,Text(metadata,"stamp"));if(cached!=null)return cached;generation=Int(state,"generation");}AudioStream? stream=path.GetExtension().ToLowerInvariant() switch {"mp3"=>AudioStreamMP3.LoadFromFile(path),"wav"=>AudioStreamWav.LoadFromFile(path),"ogg"=>AudioStreamOggVorbis.LoadFromFile(path),"flac"=>load_flac(state,path,metadata,job),_=>ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore) as AudioStream};if(stream==null)return null;var after=file_metadata(state,path,true);if(Text(after,"stamp")!=Text(metadata,"stamp"))return null;long cost=retention_cost(stream,Int(metadata,"size"),path);double sourceDuration=stream.GetLength();using(new Guard(state)){var current=Dict(Dict(state,"metadata"),path);if(generation==Int(state,"generation")&&Text(current,"stamp")==Text(metadata,"stamp")){Dict(state,"identities")[path]=new Settings {["weak"]=Variant.From(GodotObject.WeakRef(stream)),["stamp"]=metadata["stamp"],["cost"]=cost,["used"]=0L};current["duration"]=sourceDuration;retain_locked(state,path,stream);}}return stream;
    }
    public AudioStream? cached_locked(Settings state,string path,string stamp){var identity=Dict(Dict(state,"identities"),path);if(identity.Count==0||Text(identity,"stamp")!=stamp)return null;using var reference=identity["weak"].As<WeakRef>().GetRef();var stream=reference.As<AudioStream>();if(stream!=null)retain_locked(state,path,stream);return stream;}
    public void retain_locked(Settings state,string path,AudioStream stream){var identities=Dict(state,"identities");var entry=identities[path].AsGodotDictionary();long serial=Int(state,"use_serial")+1;state["use_serial"]=serial;entry["used"]=serial;long cost=Int(entry,"cost");var sources=Dict(state,"sources");if(cost>MaxCacheBytes||sources.ContainsKey(path))return;while(sources.Count>0&&(Int(state,"retained_bytes")+cost>MaxCacheBytes||sources.Count>=32)){string oldest=sources.Keys.First().AsString();foreach(var key in sources.Keys)if(Int(Dict(identities,key.AsString()),"used")<Int(Dict(identities,oldest),"used"))oldest=key.AsString();drop_strong_locked(state,oldest);}sources[path]=stream;state["retained_bytes"]=Int(state,"retained_bytes")+cost;}
    public void drop_strong_locked(Settings state,string path){var sources=Dict(state,"sources");if(sources.ContainsKey(path)){state["retained_bytes"]=Math.Max(0,Int(state,"retained_bytes")-Int(Dict(Dict(state,"identities"),path),"cost"));sources.Remove(path);}}
    public void forget_locked(Settings state,string path){drop_strong_locked(state,path);Dict(state,"identities").Remove(path);}
    public void prune_metadata_locked(Settings state,string protectedPath){var metadata=Dict(state,"metadata");if(metadata.Count<=1024)return;foreach(var key in metadata.Keys.ToArray()){if(metadata.Count<=1024)return;string path=key.AsString();if(path==protectedPath||Dict(state,"sources").ContainsKey(key)||Dict(state,"loads").ContainsKey(key))continue;var entry=Dict(Dict(state,"identities"),path);if(entry.Count>0){using var reference=entry["weak"].As<WeakRef>().GetRef();if(reference.VariantType==Variant.Type.Object&&reference.AsGodotObject()!=null)continue;}Dict(state,"identities").Remove(key);metadata.Remove(key);}}
    public double length(Settings state,Resource actor){string type=actor.Get("type_id").AsString();if(type is "video" or "video_2d")return GD.Load<CSharpScript>("res://scripts/actors/core/ActorVideo.cs").Call("length",actor).AsDouble();var values=actor.Get("values").AsGodotDictionary();var value=values.TryGetValue(new StringName("audio"),out var audio)?audio:Variant.From("");if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is AudioStream stream)return stream.GetLength();string path=SourcePath(value);if(path.Length==0)return 0;var metadata=file_metadata(state,path_key(path),false);if(Int(metadata,"size",-1)<0)return 0;if(Number(metadata,"duration",-1)>=0)return Number(metadata,"duration");return file_duration(state,path,null);}
}
